var e={knownGoodPack:{intro:{t:0,b:{t:2,i:[{t:3}],s:`為運作正常的印表機設定建立快照，封裝後可在錯誤編輯後還原。`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`取消`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`尚無任何封裝。趁印表機目前設定符合你的需求時建立一個吧。`}},files:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` 個設定檔`}]}},create:{label:{t:0,b:{t:2,i:[{t:3}],s:`新封裝`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`例如：可運作的 SV08 - 調校前`}},button:{t:0,b:{t:2,i:[{t:3}],s:`建立封裝`}}},restore:{button:{t:0,b:{t:2,i:[{t:3}],s:`還原`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`要用此封裝覆寫目前的設定嗎？`}},note:{t:0,b:{t:2,i:[{t:3}],s:`還原會覆寫你的設定檔；完成後請重新啟動 Klipper 以套用。`}},restored:{t:0,b:{t:2,i:[{t:3,v:`已還原 `},{t:4,k:`count`},{t:3,v:` 個設定檔 - 請重新啟動 Klipper 以套用`}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:`印表機忙碌中 - 目前無法還原`}},not_found:{t:0,b:{t:2,i:[{t:3}],s:`找不到封裝檔案`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`此封裝沒有任何檔案`}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:`無法還原：`},{t:4,k:`error`}]}}},delete:{button:{t:0,b:{t:2,i:[{t:3}],s:`刪除`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`刪除封裝`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`指南`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`已知良好封裝指南`}},close:{t:0,b:{t:2,i:[{t:3}],s:`關閉`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`什麼是已知良好封裝？`}},body:{t:0,b:{t:2,i:[{t:3}],s:`這是將每個印表機設定檔（printer.cfg 及其引入的檔案）儲存為具名封裝的快照。當印表機列印效果良好時，建立一個封裝，這樣若之後的編輯導致問題，你就能回退。`}}},restore:{title:{t:0,b:{t:2,i:[{t:3}],s:`還原封裝`}},body:{t:0,b:{t:2,i:[{t:3}],s:`還原會將封裝中的檔案寫回並覆寫目前的設定。印表機忙碌時會拒絕還原，且完成後你必須重新啟動 Klipper，還原的設定才會生效。`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`詞彙表`}}}},glossary:{configPack:{term:{t:0,b:{t:2,i:[{t:3}],s:`設定封裝`}},def:{t:0,b:{t:2,i:[{t:3}],s:`在某個時間點儲存的所有印表機設定檔組合。`}}},restorePoint:{term:{t:0,b:{t:2,i:[{t:3}],s:`還原點`}},def:{t:0,b:{t:2,i:[{t:3}],s:`你可以回到的已知良好狀態 - 此處指印表機運作正常時建立的封裝。`}}}}}}};export{e as default};